#include <list>
#include <algorithm>

int main() {
    std::list<int> l = {3, 1, 2};
    auto it = l.begin();

    // OK (Bidirectional)
    ++it; // Moves one forward

    // ERROR: Requires Random Access Iterator
    // it = it + 2; 

    // OK: Use list's specialized member function
    l.sort();

    // ERROR: std::sort requires Random Access Iterators for efficient implementation
    // std::sort(l.begin(), l.end()); 
}
